import Link from "next/link";import {redirect} from "next/navigation";import {DashboardNav} from "@/components/DashboardNav";import {getOverview} from "@/lib/api";
const money=(v:string)=>new Intl.NumberFormat("en-NG",{style:"currency",currency:"NGN",maximumFractionDigits:0}).format(Number(v));
export default async function Dashboard(){let data;try{data=await getOverview()}catch{redirect("/dashboard/login")}return <div className="workspace"><DashboardNav dealer={data.dealer}/><main id="main" className="dashMain"><header className="dashHead"><div><span className="eyebrow">Tuesday · Dealer overview</span><h1>Good afternoon,<br/><span className="accentWord">{data.user.name}.</span></h1></div><div className="dashHeadActions"><span>{data.user.role} access</span><Link className="button dark" href="/dashboard/inventory">Manage inventory <b>↗</b></Link></div></header><section className="statGrid">{Object.entries(data.counts).map(([key,value],i)=><article key={key}><div><span>0{i+1}</span><small>{key}</small></div><strong>{String(value).padStart(2,"0")}</strong></article>)}</section><div className="dashColumns"><section className="panel"><div className="panelHead"><div><span className="eyebrow">Inventory pulse</span><h2>Recently updated</h2></div><Link href="/dashboard/inventory">View all ↗</Link></div><div>{data.vehicles.slice(0,5).map(v=><div className="listRow" key={v.id}><div className="rowAvatar">{v.images[0]?<img src={v.images[0].url} alt=""/>:<span>{v.make[0]}</span>}</div><span><strong>{v.make} {v.model}</strong><small>{v.year} · {v.availability} · v{v.version}</small></span><b>{money(v.price)}</b></div>)}</div></section><section className="panel"><div className="panelHead"><div><span className="eyebrow">Sales desk</span><h2>Latest conversations</h2></div><Link href="/dashboard/requests">Open desk ↗</Link></div>{data.requests.length?data.requests.slice(0,5).map(r=><div className="listRow requestRow" key={r.id}><span><strong>{r.name}</strong><small>{r.kind} · {r.vehicle_title}</small></span><span className={`status ${r.status}`}>{r.status}</span></div>):<div className="panelEmpty"><span>Quiet for now.</span><p>New buyer conversations will appear here.</p></div>}</section></div><section className="panel syncPanel"><div className="panelHead"><div><span className="eyebrow">Integration health</span><h2>Marketplace delivery</h2></div><p>Dealer updates only. Marketplace visibility stays independent.</p></div><div className="eventGrid">{data.outbox.slice(0,4).map(e=><div className="eventItem" key={e.id}><span className={`eventDot ${e.status}`}/><div><strong>{e.event_type.replaceAll("."," / ")}</strong><small>Version {e.aggregate_version} · {e.status}</small></div></div>)}</div></section></main></div>}
